@import 'tailwindcss';
@import 'tw-animate-css';
@import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');

@custom-variant dark (&:is(.dark *));

:root {
  /* OOTDay Fashion Brand Colors */
  /* Primary Colors - Fashion Purple */
  --primary-50: #fef7ff;
  --primary-100: #fdeeff;
  --primary-500: #d946ef;    /* Brand purple - fashion/luxury */
  --primary-600: #c026d3;
  --primary-900: #581c87;

  /* Secondary Colors - Energy Orange */
  --secondary-50: #fff7ed;
  --secondary-100: #ffedd5;
  --secondary-500: #f97316;   /* Accent orange - energy/excitement */
  --secondary-600: #ea580c;
  --secondary-900: #9a3412;

  /* Neutral Colors */
  --neutral-50: #fafafa;     /* Backgrounds */
  --neutral-100: #f5f5f5;    /* Cards */
  --neutral-200: #e5e5e5;    /* Borders */
  --neutral-400: #a3a3a3;    /* Placeholders */
  --neutral-600: #525252;    /* Body text */
  --neutral-900: #171717;    /* Headlines */

  /* Semantic Colors */
  --success: #10b981;       /* Purchase success, saved items */
  --warning: #f59e0b;       /* Low stock, price changes */
  --error: #ef4444;         /* Errors, unavailable items */
  --info: #3b82f6;          /* Tips, information */

  /* Design System Colors - mapped for components */
  --background: var(--neutral-50);
  --foreground: var(--neutral-900);
  --card: #ffffff;
  --card-foreground: var(--neutral-900);
  --popover: #ffffff;
  --popover-foreground: var(--neutral-900);
  --primary: var(--primary-500);
  --primary-foreground: #ffffff;
  --secondary: var(--secondary-500);
  --secondary-foreground: #ffffff;
  --muted: var(--neutral-100);
  --muted-foreground: var(--neutral-600);
  --accent: var(--primary-100);
  --accent-foreground: var(--primary-900);
  --destructive: var(--error);
  --destructive-foreground: #ffffff;
  --border: var(--neutral-200);
  --input: var(--neutral-200);
  --ring: var(--primary-500);
  --chart-1: var(--primary-500);
  --chart-2: var(--secondary-500);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--info);
  --radius: 0.625rem;
  --sidebar: var(--neutral-50);
  --sidebar-foreground: var(--neutral-900);
  --sidebar-primary: var(--primary-500);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: var(--neutral-100);
  --sidebar-accent-foreground: var(--neutral-900);
  --sidebar-border: var(--neutral-200);
  --sidebar-ring: var(--primary-500);

  /* Typography Scale */
  /* Font Families */
  --font-primary: var(--font-inter), 'Inter', system-ui, -apple-system, sans-serif;
  --font-thai: 'Sarabun', var(--font-inter), 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  /* Font Sizes */
  --text-4xl: 2.25rem;     /* Hero headlines */
  --text-3xl: 1.875rem;    /* Page titles */
  --text-2xl: 1.5rem;      /* Section headers */
  --text-xl: 1.25rem;      /* Card titles */
  --text-lg: 1.125rem;     /* Large body text */
  --text-base: 1rem;       /* Default body */
  --text-sm: 0.875rem;     /* Small text */
  --text-xs: 0.75rem;      /* Captions, meta */

  /* Font Weights */
  --font-light: 300;
  --font-normal: 400;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;

  /* Spacing System */
  --space-1: 0.25rem;      /* 4px */
  --space-2: 0.5rem;       /* 8px */
  --space-3: 0.75rem;      /* 12px */
  --space-4: 1rem;         /* 16px */
  --space-6: 1.5rem;       /* 24px */
  --space-8: 2rem;         /* 32px */
  --space-12: 3rem;        /* 48px */
  --space-16: 4rem;        /* 64px */

  /* Responsive Breakpoints */
  --breakpoint-sm: 640px;   /* Small tablets */
  --breakpoint-md: 768px;   /* Tablets */
  --breakpoint-lg: 1024px;  /* Small desktops */
  --breakpoint-xl: 1280px;  /* Large desktops */
  --breakpoint-2xl: 1536px; /* Extra large */

  /* Layout Grid Margins */
  --margin-mobile: 16px;
  --margin-tablet: 24px;
  --margin-desktop: 32px;
}

.dark {
  /* Dark mode adjustments for OOTDay colors */
  --background: var(--neutral-900);
  --foreground: var(--neutral-50);
  --card: #1a1a1a;
  --card-foreground: var(--neutral-50);
  --popover: #1a1a1a;
  --popover-foreground: var(--neutral-50);
  --primary: var(--primary-500);
  --primary-foreground: #ffffff;
  --secondary: var(--secondary-500);
  --secondary-foreground: #ffffff;
  --muted: #2a2a2a;
  --muted-foreground: var(--neutral-400);
  --accent: var(--primary-900);
  --accent-foreground: var(--primary-100);
  --destructive: var(--error);
  --destructive-foreground: #ffffff;
  --border: #2a2a2a;
  --input: #2a2a2a;
  --ring: var(--primary-500);
  --chart-1: var(--primary-500);
  --chart-2: var(--secondary-500);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--info);
  --sidebar: #1a1a1a;
  --sidebar-foreground: var(--neutral-50);
  --sidebar-primary: var(--primary-500);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #2a2a2a;
  --sidebar-accent-foreground: var(--neutral-50);
  --sidebar-border: #2a2a2a;
  --sidebar-ring: var(--primary-500);
}

@theme inline {
  /* Font Configuration */
  --font-sans: var(--font-primary);
  --font-display: var(--font-display);

  /* Color System */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* OOTDay Brand Colors for Tailwind */
  --color-primary-50: var(--primary-50);
  --color-primary-100: var(--primary-100);
  --color-primary-500: var(--primary-500);
  --color-primary-600: var(--primary-600);
  --color-primary-900: var(--primary-900);
  --color-secondary-50: var(--secondary-50);
  --color-secondary-100: var(--secondary-100);
  --color-secondary-500: var(--secondary-500);
  --color-secondary-600: var(--secondary-600);
  --color-secondary-900: var(--secondary-900);
  --color-neutral-50: var(--neutral-50);
  --color-neutral-100: var(--neutral-100);
  --color-neutral-200: var(--neutral-200);
  --color-neutral-400: var(--neutral-400);
  --color-neutral-600: var(--neutral-600);
  --color-neutral-900: var(--neutral-900);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-error: var(--error);
  --color-info: var(--info);

  /* Chart Colors */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  /* Border Radius */
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* Spacing Scale */
  --spacing-1: var(--space-1);
  --spacing-2: var(--space-2);
  --spacing-3: var(--space-3);
  --spacing-4: var(--space-4);
  --spacing-6: var(--space-6);
  --spacing-8: var(--space-8);
  --spacing-12: var(--space-12);
  --spacing-16: var(--space-16);

  /* Typography Scale */
  --font-size-xs: var(--text-xs);
  --font-size-sm: var(--text-sm);
  --font-size-base: var(--text-base);
  --font-size-lg: var(--text-lg);
  --font-size-xl: var(--text-xl);
  --font-size-2xl: var(--text-2xl);
  --font-size-3xl: var(--text-3xl);
  --font-size-4xl: var(--text-4xl);

  /* Sidebar Colors */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}
